 const record=useMemo(()=>digestFor(world,local.id),[world,local.id]),draft=local.draft,source=draft.sources.find(s=>s.id===local.sourceId),item=draft.items.find(i=>i.id===local.itemId),snapshot=digestSnapshot(draft),currentSnapshot=record?digestSnapshot(digestDraftFrom(record)):'',dirty=!record||snapshot!==currentSnapshot,stale=!!record&&local.version!==String(record.version),archived=record?.status==='archived';
