 const hiddenItemIds:readonly string[]=[...new Set([...(record?.unavailableItemIds||[]),...draft.items.filter(i=>i.evidence.some(e=>{const s=draft.sources.find(s=>s.id===e.sourceId);return !s||!digestSourceState(world,s).ready||s.version!==e.sourceVersion||e.contextSnapshot!==digestContextSnapshot(draft)||!s.excerpt.includes(e.quote);})||changedContext&&acceptedItemIds.includes(i.id)).map(i=>i.id)])],hiddenSourceIds=draft.sources.filter(s=>blocked||!s.selected).map(s=>s.id),mask=hiddenItemIds.join('|')+';'+hiddenSourceIds.join('|');
