 const addItem=()=>{keyboard.hide();const id=localPreviewId();patch({items:[...draft.items,{id,title:'',summary:'',topicIds:[],sourceIds:[],publishedDate:'',uncertainty:'',annotation:'',evidence:[]}]});setLocal(s=>({...s,itemId:id}));setMode('item');};
